1	// Command orb-registry-catalog serves the HTTP API described in README.md.
2	package main
3	
4	import (
5		"log"
6		"os"
7	
8		"github.com/Bob-xisuke/orb-registry-catalog/internal/api"
9		"github.com/Bob-xisuke/orb-registry-catalog/internal/store"
10	)
11	
12	func main() {
13		address := os.Getenv("ADDR")
14		if address == "" {
15			address = "127.0.0.1:8080"
16		}
17		databasePath := os.Getenv("DB_PATH")
18		if databasePath == "" {
19			databasePath = "orb-registry-catalog.db"
20		}
21	
22		st, err := store.Open(databasePath)
23		if err != nil {
24			log.Fatalf("open store: %v", err)
25		}
26		defer st.Close()
27	
28		if err := api.NewRouter(st).Run(address); err != nil {
29			log.Fatalf("serve: %v", err)
30		}
31	}
